=over 4

=item * C<STATE_UNSPECIFIED> => C<0>

=item * C<INACTIVE> => C<1>

=item * C<ACTIVE> => C<2>

=item * C<CREATING> => C<3>

=item * C<DELETING> => C<4>

=back

