=head2 Google::Cloud::Vmwareengine::V1::VmwareengineResources::PeeringRoute

Exchanged network peering route.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->dest_range() >> / C<< $msg->dest_range($value) >>

Type: C<String>

