=over 4

=item * C<TYPE_UNSPECIFIED> => C<0>

=item * C<PRIVATE_SERVICE_ACCESS> => C<1>

=item * C<NETAPP_CLOUD_VOLUMES> => C<2>

=item * C<DELL_POWERSCALE> => C<3>

=item * C<THIRD_PARTY_SERVICE> => C<4>

=back

=head3 Enum: PrivateConnection::RoutingMode

=over 4

